import logging
import queue
import threading

logger = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Consumes items from a queue on a background thread, passing each to a callback."""

    def __init__(self, work_queue, handle_item, name="queue-worker"):
        self.work_queue = work_queue
        self.handle_item = handle_item
        self.thread = threading.Thread(target=self._consume, name=name, daemon=True)
        self.processed_count = 0
        self.error_count = 0

    def start(self):
        self.thread.start()
        return self

    def _consume(self):
        while True:
            item = self.work_queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.handle_item(item)
                self.processed_count += 1
            except Exception:
                self.error_count += 1
                logger.exception("worker callback failed for item %r", item)
            finally:
                self.work_queue.task_done()

    def submit(self, item):
        self.work_queue.put(item)

    def drain(self):
        """Block until every item queued so far has been handled."""
        self.work_queue.join()

    def stop(self, timeout=None):
        """Ask the thread to finish the current item and exit."""
        self.work_queue.put(_SHUTDOWN)
        self.thread.join(timeout)
        return not self.thread.is_alive()

    def __enter__(self):
        return self.start()

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    with QueueWorker(queue.Queue(), lambda url: logger.info("fetching %s", url)) as worker:
        for page in range(5):
            worker.submit(f"https://example.com/page/{page}")
        worker.drain()
